const MAX_VIDEO_MB = 50;
const MAX_IMAGE_MB = 3;
async function comprimirImagem(file, maxMB = MAX_IMAGE_MB) {
    if (!file.type.startsWith('image/')) return file; // vídeos: sem compressão
    return new Promise((resolve, reject)=>{
        const img = new Image();
        const objectUrl = URL.createObjectURL(file);
        img.onload = ()=>{
            URL.revokeObjectURL(objectUrl);
            const canvas = document.createElement('canvas');
            const MAX_DIM = 1920;
            let { width, height } = img;
            if (width > MAX_DIM || height > MAX_DIM) {
                if (width > height) {
                    height = Math.round(height * MAX_DIM / width);
                    width = MAX_DIM;
                } else {
                    width = Math.round(width * MAX_DIM / height);
                    height = MAX_DIM;
                }
            }
            canvas.width = width;
            canvas.height = height;
            canvas.getContext('2d').drawImage(img, 0, 0, width, height);
            let quality = 0.9;
            const attempt = ()=>canvas.toBlob((blob)=>{
                    if (!blob) return reject(new Error('Falha ao comprimir'));
                    if (blob.size > maxMB * 1024 * 1024 && quality > 0.3) {
                        quality -= 0.1;
                        attempt();
                    } else resolve(new File([
                        blob
                    ], file.name.replace(/\.[^.]+$/, '.jpg'), {
                        type: 'image/jpeg'
                    }));
                }, 'image/jpeg', quality);
            attempt();
        };
        img.onerror = reject;
        img.src = objectUrl;
    });
}
/** Upload direto ao Supabase via URL assinada (evita limite 413 do Vercel). */ async function uploadMidia(file, saborId, storeSlug) {
    const signRes = await fetch('/api/cmv/foto', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            saborId,
            storeSlug,
            contentType: file.type || 'application/octet-stream',
            fileName: file.name
        })
    });
    const signData = await signRes.json().catch(()=>({
            error: `HTTP ${signRes.status}`
        }));
    if (!signRes.ok) throw new Error(signData.error || `Falha ao preparar upload (${signRes.status})`);
    // Formato esperado pelo Storage (igual ao uploadToSignedUrl do supabase-js)
    const body = new FormData();
    body.append('cacheControl', '3600');
    body.append('', file);
    const uploadRes = await fetch(signData.signedUrl, {
        method: 'PUT',
        headers: {
            'x-upsert': 'false'
        },
        body
    });
    if (!uploadRes.ok) {
        const detail = await uploadRes.text().catch(()=>'');
        throw new Error(detail || `Upload falhou (${uploadRes.status})`);
    }
    return signData.publicUrl;
}
function isVideo(url) {
    return /\.(mp4|mov|webm|avi|mkv)(\?|$)/i.test(url);
}
async function downloadMidia(url, nome) {
    const cleanUrl = url.split('?')[0];
    const ext = cleanUrl.split('.').pop() ?? 'jpg';
    const res = await fetch(url);
    const blob = await res.blob();
    const blobUrl = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = blobUrl;
    a.download = `${nome}.${ext}`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(blobUrl);
}
